CustomField.formula:
/*First if completed same day*/
if( DateValue(Previous_Status_Date_Time__c)=DateValue(CreatedDate),
/*Adjusts Closed Hour/Minute if it's before or after hours*/
if(Created_Date_Hour__c<8, 8, if(Created_Date_Hour__c>17, 17, Created_Date_Hour__c))+
if(Created_Date_Hour__c<8 || Created_Date_Hour__c>17, 0, Minute(TimeValue(CreatedDate))/60)
-
/*Adjust Created Hour/Minute if it's before or after hours*/
(if(Previous_Status_Hour__c<8, 8, if(Previous_Status_Hour__c>17, 17, Previous_Status_Hour__c))+
if(Previous_Status_Hour__c<8 || Previous_Status_Hour__c>17,0, Minute(TimeValue(Previous_Status_Date_Time__c)))/60),



/*If not the same day, calcs hours of first day, if after hours or weekend rounds Created down and Completed up*/
if( Weekday(DateValue(Previous_Status_Date_Time__c))=7 || Weekday(DateValue(Previous_Status_Date_Time__c))=0 || Previous_Status_Hour__c>=17 , 0,
/*If it's before hours, limit to 8 hours*/
if(Previous_Status_Hour__c<8, 8, 17-(Previous_Status_Hour__c))+
if(Previous_Status_Hour__c<8 || Previous_Status_Hour__c>17, 0, (Minute(TimeValue(Previous_Status_Date_Time__c))/60))
)
+
/*Calcs days between and converts to hours by multiplying by 8 workhours*/
(CASE( WEEKDAY(DateValue(Previous_Status_Date_Time__c)),
/*This excludes End Dates e.g. Mon Tuesday Wednesday = 1*/
1 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
2 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
3 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
4 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
5 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
6 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
7 , CASE( MOD( DateValue(CreatedDate)-DateValue(Previous_Status_Date_Time__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
999)
+
(FLOOR(( DateValue(CreatedDate) - DateValue(Previous_Status_Date_Time__c) )/7)*5))*8
+
/*Calcs days at the end*/
/*If it's before hours, limit to 8 hours*/
if(Created_Date_Hour__c<8, 0, if(Created_Date_Hour__c>17, 17, Created_Date_Hour__c-8))+
if(Created_Date_Hour__c<8 || Created_Date_Hour__c>17, 0, (Minute(TimeValue(CreatedDate))/60))

)
